CREATE TABLE execution_attempts(operation_id TEXT NOT NULL REFERENCES operations(id), ordinal INTEGER NOT NULL CHECK(ordinal>0), backend_id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN('prepared','running','waiting_external','cancel_requested','terminal')), revision INTEGER NOT NULL CHECK(revision>0), payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(operation_id,ordinal)) STRICT;
CREATE TABLE execution_results(operation_id TEXT NOT NULL, ordinal INTEGER NOT NULL, outcome TEXT NOT NULL, side_effect TEXT NOT NULL, receipt_artifact_id TEXT NOT NULL REFERENCES artifacts(id), payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(operation_id,ordinal), FOREIGN KEY(operation_id,ordinal) REFERENCES execution_attempts(operation_id,ordinal)) STRICT;
CREATE TABLE execution_operational_state(operation_id TEXT NOT NULL, ordinal INTEGER NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), progress TEXT NOT NULL CHECK(json_valid(progress)), PRIMARY KEY(operation_id,ordinal), FOREIGN KEY(operation_id,ordinal) REFERENCES execution_attempts(operation_id,ordinal)) STRICT;
CREATE TRIGGER immutable_execution_result_update BEFORE UPDATE ON execution_results BEGIN SELECT RAISE(ABORT,'immutable terminal result'); END;
CREATE TRIGGER immutable_execution_result_delete BEFORE DELETE ON execution_results BEGIN SELECT RAISE(ABORT,'immutable terminal result'); END;
